class Widget {
public:
  // Overload with perfect match for two ints
  Widget(int i, double d) { /* ... */ }

  // Initializer list constructor
  Widget(std::initializer_list<long double> il) { /* ... */ }

  operator float() const { return 0.0f; } // Conversion function
};

Widget w1(10, 5.0);   // Uses parens, calls Widget(int, double)
Widget w2{10, 5.0};   // Uses braces, calls Widget(std::initializer_list<long double>)

Widget source;
Widget w3(source);    // Uses parens, calls copy constructor (not shown)
Widget w4{source};    // Uses braces, converts source to float, then to long double,
                      // then calls initializer_list constructor with one element.
